public with sharing class CheckWeather {
    @InvocableMethod(label='Check Weather'
        description='Check weather at Coral Cloud Resorts at a specific date')
    public static List<WeatherResponse> getWeather(List<WeatherRequest> requests) {
        List<WeatherResponse> results = new List<WeatherResponse>();
        for (WeatherRequest req : requests) {
            WeatherService.Weather w =
                WeatherService.getResortWeather(Datetime.newInstance(req.dateToCheck, Time.newInstance(12, 0, 0, 0)));
            WeatherResponse res = new WeatherResponse();
            res.minTemperature = w.minTemperatureC;
            res.maxTemperature = w.maxTemperatureC;
            res.temperatureDescription = w.description;
            results.add(res);
        }
        return results;
    }
    public class WeatherRequest {
        @InvocableVariable(required=true description='Date to check (yyyy-MM-dd)')
        public Date dateToCheck;
    }
    public class WeatherResponse {
        @InvocableVariable(description='Minimum temperature') public Decimal minTemperature;
        @InvocableVariable(description='Maximum temperature') public Decimal maxTemperature;
        @InvocableVariable(description='Weather description') public String temperatureDescription;
    }
}
